ROOT=Path(__file__).resolve().parents[1]
P=ROOT/'rentegap-boliglan.html'
html='''<!doctype html><html lang="nb"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rentegap-sjekk: Er boliglånsrenten din over markedet? | Sparesjekk</title><meta name="description" content="Sammenlign boliglånsrenten din med siste offisielle SSB-statistikk og se hva rentegapet tilsvarer i kroner per år."><meta name="robots" content="index,follow"><link rel="canonical" href="https://sparesjekk.no/rentegap-boliglan.html"><link rel="stylesheet" href="style.css?v=26"><link rel="stylesheet" href="design-v36.css"><link rel="stylesheet" href="design-v44.css"></head><body><header class="header"><a class="logo" href="index.html">Spare<span>sjekk</span></a><nav class="topnav"><a href="boliglan.html">Boliglån</a><a href="forbrukslan.html">Forbrukslån</a><a href="kredittkort.html">Kredittkort</a><a href="guider.html">Guider</a></nav></header><main><article class="article cornerstone rate-gap-asset"><p class="eyebrow">BOLIGLÅN · OFFISIELL REFERANSE</p><h1>Rentegap-sjekk: Hvordan ligger boliglånsrenten din mot markedet?</h1><p class="lead">Legg inn renten og restgjelden din. Vi sammenligner med siste publiserte gjennomsnitt for <strong>nye boliglån</strong> fra Statistisk sentralbyrå (SSB).</p><section class="rate-gap-source"><strong>Offisiell referanse: 5,29 %</strong><p>SSBs månedsstatistikk viser 5,29 % gjennomsnittlig rente på nye lån med pant i bolig til husholdninger i juli 2026. Utestående boliglån var 5,31 %. Statistikken ble publisert 27. august 2026, med neste oppdatering 25. september 2026.</p><p><a href="https://www.ssb.no/bank-og-finansmarked/finansinstitusjoner-og-andre-finansielle-foretak/statistikk/renter-i-banker-og-kredittforetak" rel="noopener" target="_blank">Kilde: SSB – Renter i banker og kredittforetak →</a></p></section><section class="rate-gap-tool"><h2>Regn ut ditt rentegap</h2><div class="rate-gap-grid"><label>Din effektive boliglånsrente (%)<input id="rg-rate" inputmode="decimal" placeholder="f.eks. 5,65"></label><label>Restgjeld (kr)<input id="rg-loan" inputmode="numeric" placeholder="f.eks. 3000000"></label></div><button id="rg-calc" type="button">Sjekk rentegapet</button><div id="rg-result" class="rate-gap-result" hidden></div><p class="article-note">Dette er en indikasjon, ikke et pristilbud. SSB-tallet er et gjennomsnitt for nye boliglån og sier ikke hvilken rente du personlig kan få. Banker priser blant annet etter sikkerhet, belåningsgrad og kundens økonomi.</p></section><section><h2>Hva betyr referansen?</h2><p>Den viser gjennomsnittsrenten i SSBs månedsutvalg, ikke en «beste rente». Den er nyttig som temperaturmåler: ligger du tydelig høyere, kan det være et signal om å undersøke vilkårene dine nærmere. Ligger du rundt eller under gjennomsnittet, kan andre vilkår fortsatt være relevante.</p></section><section><h2>Hvorfor regne forskjellen i kroner?</h2><p>Prosentpoeng er abstrakte. På et stort boliglån kan noen tideler prosentpoeng bli et merkbart årsbeløp. Beregningen her er et enkelt overslag: restgjeld × renteforskjell. Den tar ikke hensyn til nedbetaling gjennom året, skatt, gebyrer eller andre vilkår.</p></section><section class="related-box"><h2>Videre</h2><div class="related-links"><a href="guide-forhandle-rente.html">Forhandle med dagens bank →</a><a href="boliglanskalkulator-renteforskjell.html">Sammenlign to konkrete renter →</a><a href="guide-sammenligne-boliglan.html">Slik sammenligner du boliglån →</a></div></section></article></main><footer><div class="footer-logo">Spare<span>sjekk</span></div><p>En uavhengig informasjonsside om privatøkonomi. Vi er ikke en bank og tilbyr ikke personlig økonomisk rådgivning.</p></footer><script>
(function(){var benchmark=5.29,btn=document.getElementById('rg-calc'),out=document.getElementById('rg-result');
function num(id){return Number((document.getElementById(id).value||'').replace(/\s/g,'').replace(',','.'))}
btn.addEventListener('click',function(){var rate=num('rg-rate'),loan=num('rg-loan');if(!(rate>0)||!(loan>0)){out.hidden=false;out.innerHTML='<strong>Fyll inn rente og restgjeld.</strong>';return}var gap=rate-benchmark,annual=Math.abs(loan*gap/100),cls=gap>.15?'over':gap<-.15?'under':'around';var title=cls==='over'?'Renten din ligger over SSB-referansen':cls==='under'?'Renten din ligger under SSB-referansen':'Renten din ligger omtrent rundt SSB-referansen';var text=cls==='over'?'Forskjellen tilsvarer grovt <strong>'+annual.toLocaleString('nb-NO',{maximumFractionDigits:0})+' kr per år</strong> på dagens restgjeld før nedbetaling, skatt og gebyrer.':'Forskjellen mot referansen er grovt <strong>'+annual.toLocaleString('nb-NO',{maximumFractionDigits:0})+' kr per år</strong> på dagens restgjeld før nedbetaling, skatt og gebyrer.';var next=cls==='over'?'<a class="cta" data-revenue-event="commercial_route" data-revenue-context="rate_gap_above_v1" href="sjekk/boliglan/?intent=sammenligne">Sammenlign boliglånsalternativer →</a><a href="guide-forhandle-rente.html">Eller bruk tallet til å forhandle med banken →</a>':'<a class="cta" data-revenue-event="problem_route" data-revenue-context="rate_gap_check_v1" href="boliglanskalkulator-renteforskjell.html">Sammenlign med et konkret tilbud →</a><a href="guide-forhandle-rente.html">Se hvordan du kan forhandle →</a>';out.innerHTML='<h3>'+title+'</h3><p>Din rente: <strong>'+rate.toLocaleString('nb-NO',{minimumFractionDigits:2,maximumFractionDigits:2})+' %</strong> · SSB nye boliglån: <strong>5,29 %</strong> · gap: <strong>'+gap.toLocaleString('nb-NO',{minimumFractionDigits:2,maximumFractionDigits:2})+' prosentpoeng</strong>.</p><p>'+text+'</p><div class="rate-gap-actions">'+next+'</div>';out.hidden=false;if(typeof window.gtag==='function')window.gtag('event','rate_gap_result',{result_class:cls,source_path:location.pathname});});})();
</script><script data-sparesjekk-revenue-tracking="v1">document.addEventListener('click',function(e){var a=e.target.closest('[data-revenue-event]');if(!a)return;if(typeof window.gtag!=='function')return;var n=a.dataset.revenueEvent,p={revenue_stage:n,source_path:location.pathname,destination:a.getAttribute('href')||'',link_text:(a.textContent||'').trim().slice(0,100)};if(a.dataset.revenueContext)p.revenue_context=a.dataset.revenueContext;gtag('event',n,p);});</script></body></html>'''
